describe('Locked Out User Login Error Message', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
  });

  it('should display locked out error message when attempting to log in with locked user', () => {
    cy.get('[data-test="username"]').type('locked_out_user');
    cy.get('[data-test="password"]').type('secret_sauce');
    cy.get('[data-test="login-button"]').click();

    cy.get('[data-testid="error"]').should('be.visible');
    cy.get('[data-testid="error"]').should('contain', 'Sorry, this user has been locked out');
    cy.get('[data-test="login-container"]').should('be.visible');
    cy.get('[data-test="username"]').should('have.value', 'locked_out_user');
    cy.get('[data-test="password"]').should('have.value', 'secret_sauce');
  });

  it('should not navigate to inventory page when locked out user attempts login', () => {
    cy.get('[data-test="username"]').type('locked_out_user');
    cy.get('[data-test="password"]').type('secret_sauce');
    cy.get('[data-test="login-button"]').click();

    cy.get('[data-testid="error"]').should('be.visible');
    cy.get('[data-test="inventory-container"]').should('not.exist');
    cy.get('[data-test="login-container"]').should('be.visible');
    cy.get('[data-test="login-container"]').should('contain', 'Sorry, this user has been locked out');
  });
});
